//! ChildNode variadic methods use genuine native nodes and specified mutation boundaries.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://child-variadic.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn child_node_variadic_canonical_mixin_brands_descriptors_and_unscopables(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var proto of [Element.prototype,CharacterData.prototype,DocumentType.prototype]){for(var name of ['before','after','replaceWith']){var desc=Object.getOwnPropertyDescriptor(proto,name);if(!desc||typeof desc.value!=='function'||desc.value.name!==name||desc.value.length!==0||!desc.writable||!desc.enumerable||!desc.configurable)throw 'ChildNode canonical descriptor';}var blocked=Object.getOwnPropertyDescriptor(proto,Symbol.unscopables);if(!blocked||blocked.writable||blocked.enumerable||!blocked.configurable||Object.getPrototypeOf(blocked.value)!==null)throw 'ChildNode unscopables metadata';for(var name of ['before','after','replaceWith','remove']){if(blocked.value[name]!==true)throw 'ChildNode unscopables flag';}}
for(var name of ['append','prepend','replaceChildren']){if(Element.prototype[Symbol.unscopables][name]!==true)throw 'preserved ParentNode unscopables';}for(var proto of [Document.prototype,DocumentFragment.prototype,Attr.prototype]){if(Object.hasOwn(proto,'before')||Object.hasOwn(proto,'after')||Object.hasOwn(proto,'replaceWith'))throw 'ChildNode mixin availability';}var calls=0,arg={toString:function(){calls++;return 'x';}};for(var bad of [{},window,document,document.createDocumentFragment(),document.createAttribute('x')]){var error;try{Element.prototype.before.call(bad,arg);}catch(e){error=e;}if(!(error instanceof TypeError)||calls)throw 'brand guard before conversion';}
"#);}
#[test]
fn child_node_variadic_viable_siblings_exclude_receiver_and_duplicate_arguments_before_staging(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.before!=='function')throw 'missing ChildNode before';for(var owner of [document,new Document(),document.implementation.createHTMLDocument('inert'),document.createElement('template').content.ownerDocument]){var host=owner.createElement('div'),a=owner.createElement('a'),b=owner.createElement('b'),c=owner.createElement('i'),z=owner.createElement('span');host.append(a,b,c,z);b.before(b,a,'X',c,b);if(host.childNodes.length!==5||host.childNodes[0]!==a||host.childNodes[1].data!=='X'||host.childNodes[2]!==c||host.childNodes[3]!==b||host.lastChild!==z)throw 'viable previous excluding supplied aliases';host.replaceChildren(a,b,c,z);b.after(b,c,'Y',a,b);if(host.childNodes.length!==5||host.childNodes[0]!==c||host.childNodes[1].data!=='Y'||host.childNodes[2]!==a||host.childNodes[3]!==b||host.lastChild!==z)throw 'viable next excluding supplied aliases';host.replaceChildren(a,b,c,z);b.replaceWith('L',b,c,'R');if(host.childNodes.length!==6||host.firstChild!==a||host.childNodes[1].data!=='L'||host.childNodes[2]!==b||host.childNodes[3]!==c||host.childNodes[4].data!=='R'||host.lastChild!==z)throw 'receiver moved during replacement staging';}
"#);}
#[test]
fn child_node_variadic_native_text_comment_pi_doctype_owners_and_raw_utf16(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof CharacterData.prototype.before!=='function')throw 'missing CharacterData ChildNode before';for(var owner of [document,new Document(),document.createElement('template').content.ownerDocument]){var host=owner.createElement('div'),text=owner.createTextNode('text'),comment=owner.createComment('comment'),pi=owner.createProcessingInstruction('target','data');host.append(text,comment,pi);text.before('A'+String.fromCharCode(55296)+'Z');comment.after(null,undefined,false,12);if(host.firstChild.nodeType!==3||host.firstChild.ownerDocument!==owner||host.firstChild.data.charCodeAt(1)!==55296||host.childNodes[3].data!=='null'||host.childNodes[4].data!=='undefined'||host.childNodes[5].data!=='false'||host.childNodes[6].data!=='12'||host.lastChild!==pi)throw 'CharacterData ordered exact text and owner';pi.replaceWith('new');if(pi.parentNode!==null||host.lastChild.data!=='new')throw 'native PI replacement';}var owner=new Document(),root=owner.createElement('Root'),dtype=owner.implementation.createDocumentType('Root','','');owner.append(root);root.before(dtype);var comment=owner.createComment('lead');dtype.before(comment);if(owner.firstChild!==comment||owner.childNodes[1]!==dtype||owner.documentElement!==root)throw 'doctype ChildNode actual owner';dtype.replaceWith();if(owner.doctype!==null||dtype.parentNode!==null||owner.documentElement!==root)throw 'doctype removal by replacement';
"#);}
#[test]
fn child_node_variadic_binding_conversion_precedes_parent_lookup_and_detached_noop_allocates_no_native_nodes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.before!=='function')throw 'missing ChildNode before';var host=document.createElement('div'),node=document.createElement('span'),marker={},calls=0,arg={toString:function(){calls++;host.appendChild(node);return 'before';}};node.before(arg);if(calls!==1||host.firstChild.data!=='before'||host.lastChild!==node)throw 'binding conversion before parent lookup';node.remove();var caught;try{node.after({toString:function(){calls++;throw marker;}});}catch(e){caught=e;}if(caught!==marker||calls!==2||node.parentNode!==null)throw 'detached binding conversion abrupt';var detached=document.createTextNode('detached');
"#);let native=(d.nodes.len(),p.state.dom_commits);let limit=p.state.retained_limit;p.state.retained_limit=p.state.retained;
 run(&mut d,&mut f,&mut p,"detached.before('text');detached.after('text');detached.replaceWith('text');");assert_eq!((d.nodes.len(),p.state.dom_commits),native);p.state.retained_limit=limit;}
#[test]
fn child_node_variadic_actual_records_ranges_and_empty_replacement_use_native_transactions(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof CharacterData.prototype.replaceWith!=='function')throw 'missing ChildNode replaceWith';for(var owner of [document,new Document(),document.createElement('template').content.ownerDocument]){var host=owner.createElement('div'),old=owner.createTextNode('old'),end=owner.createComment('end');host.append(old,end);var list=host.childNodes,range=owner.createRange();range.setStart(old,1);range.setEnd(old,2);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true});old.replaceWith('new',owner.createElement('b'));var records=watch.takeRecords();if(records.length!==1||records[0].target!==host||records[0].removedNodes.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes.length!==2||records[0].nextSibling!==end||old.parentNode!==null||list.length!==3||range.startContainer!==host||range.startOffset!==0||range.endContainer!==host||range.endOffset!==0)throw 'native replacement record and range';var first=host.firstChild;first.before();first.after();if(watch.takeRecords().length)throw 'empty sibling noops';first.replaceWith();records=watch.takeRecords();if(records.length!==1||records[0].removedNodes[0]!==first||records[0].addedNodes.length||first.parentNode!==null||list.length!==2)throw 'empty replacement removes actual receiver';watch.disconnect();}
"#);}
#[test]
fn child_node_variadic_later_staging_failure_retains_author_and_earlier_native_moves(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.before!=='function')throw 'missing ChildNode before';for(var name of ['before','after','replaceWith']){var host=document.createElement('div'),node=document.createElement('span'),source=document.createElement('div'),a=document.createElement('b'),b=document.createElement('i');host.appendChild(node);source.append(a,b);var watch=new MutationObserver(function(){});watch.observe(source,{childList:true});var error;try{node[name](a,document,b);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError'||node.parentNode!==host||host.firstChild!==node||a.parentNode===source||a.parentNode.nodeType!==11||b.parentNode!==source||watch.takeRecords().length!==1)throw 'later staging failure preserves actual earlier native moves';var marker={},arg={toString:function(){host.appendChild(a);throw marker;}},caught;try{node[name](arg);}catch(e){caught=e;}if(caught!==marker||a.parentNode!==host||host.lastChild!==a)throw 'author conversion effects retained';}
"#);}
#[test]
fn child_node_variadic_saved_child_method_owner_guard_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.before!=='function')throw 'missing ChildNode before';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var before=frame.contentWindow.Element.prototype.before,host=document.createElement('div'),node=document.createElement('span'),calls=0,arg={toString:function(){calls++;return 'saved';}};host.appendChild(node);before.call(node,'borrowed');if(host.firstChild.data!=='borrowed')throw 'borrowed captured owner';
"#);p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("before.call(node,arg)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");p.set_location(&crate::navigation::address("https://child-variadic.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(calls||host.childNodes.length!==2)throw 'captured owner guard before effects';node.after('fresh');if(host.lastChild.data!=='fresh')throw 'fresh recovery';");}
#[test]
fn child_node_variadic_single_string_refusal_preserves_receiver_tree_records_ranges_and_recovers(){
 for method in ["before","after","replaceWith"]{for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"if(typeof CharacterData.prototype.before!=='function')throw 'missing ChildNode before';var host=document.createElement('div'),text=document.createTextNode('old');host.appendChild(text);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true});var range=document.createRange();range.setStart(text,1);range.setEnd(text,2);"#);let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute(&format!("text.{method}('new text needing native storage')"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||host.lastChild!==text||text.data!=='old'||watch.takeRecords().length||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==2)throw 'native refusal before receiver effects';text.after('fresh');if(host.textContent!=='oldfresh'||watch.takeRecords().length!==1)throw 'fresh recovery';");}}
}

#[test]
fn child_node_variadic_single_self_calls_preserve_actual_removal_records_and_range_updates(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var owner of [document,new Document(),document.createElement('template').content.ownerDocument]){for(var method of ['before','after','replaceWith']){var host=owner.createElement('div'),text=owner.createTextNode('same'),end=owner.createComment('end');host.append(text,end);var range=owner.createRange();range.setStart(text,1);range.setEnd(text,2);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true});text[method](text);var records=watch.takeRecords();if(host.firstChild!==text||host.lastChild!==end||records.length!==2||records[0].removedNodes[0]!==text||records[0].addedNodes.length||records[1].addedNodes[0]!==text||records[1].removedNodes.length||range.startContainer!==host||range.startOffset!==0||range.endContainer!==host||range.endOffset!==0)throw 'single self operation preserves native removal and reinsertion';watch.disconnect();}}
"#);}
#[test]
fn child_node_variadic_shared_parent_prepend_adjusts_single_self_reference_before_native_move(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var owner of [document,new Document()]){var host=owner.createElement('div'),text=owner.createTextNode('same'),end=owner.createComment('end');host.append(text,end);var range=owner.createRange();range.setStart(text,1);range.setEnd(text,2);var watch=new MutationObserver(function(){});watch.observe(host,{childList:true});host.prepend(text);var records=watch.takeRecords();if(host.firstChild!==text||host.lastChild!==end||records.length!==2||records[0].removedNodes[0]!==text||records[1].addedNodes[0]!==text||range.startContainer!==host||range.startOffset!==0)throw 'shared variadic preinsert self reference';watch.disconnect();}
"#);}
#[test]
fn child_node_variadic_viable_reference_moved_by_fragment_expansion_throws_after_real_staging(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var owner of [document,new Document()]){for(var method of ['before','after','replaceWith']){var parent=owner.createDocumentFragment(),a=owner.createElement('a'),b=owner.createElement('b'),c=owner.createElement('i');parent.append(a,b,c);var watch=new MutationObserver(function(){});watch.observe(parent,{childList:true});var error;try{b[method](parent,'tail');}catch(e){error=e;}var records=watch.takeRecords();if(!(error instanceof DOMException)||error.name!=='NotFoundError'||parent.firstChild!==null||b.parentNode===parent||b.parentNode.nodeType!==11||b.parentNode.firstChild!==a||b.parentNode.lastChild.data!=='tail'||records.length!==1||records[0].removedNodes.length!==3)throw 'viable reference moved by expanded native fragment';watch.disconnect();}}
"#);}
